package com.aistock.prediction.comparison;
import com.sun.net.httpserver.HttpServer;import com.fasterxml.jackson.databind.ObjectMapper;import java.net.*;import java.util.*;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
class ComparisonMarketClientTest {
 @Test void acceptsLargeButBoundedEvidenceAndUsesToken()throws Exception{var execution=UUID.randomUUID().toString();var bundle=UUID.randomUUID().toString();var server=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);server.createContext("/",e->{assertEquals("fixture",e.getRequestHeaders().getFirst("X-Service-Token"));assertEquals("COMPARISON",e.getRequestHeaders().getFirst("X-Market-Use-Purpose"));assertEquals(execution,e.getRequestHeaders().getFirst("X-Market-Use-Operation"));assertEquals(bundle,e.getRequestHeaders().getFirst("X-Market-Use-Bundle"));byte[] bytes=("{\"code\":\"OK\",\"data\":{\"padding\":\""+"x".repeat(70000)+"\"}}").getBytes();e.sendResponseHeaders(200,bytes.length);e.getResponseBody().write(bytes);e.close();});server.start();var selected=new com.aistock.common.marketlifecycle.MarketUseRecords.Selector("COMPARISON_EVIDENCE",null,List.of(new com.aistock.common.marketlifecycle.MarketUseRecords.EvidenceBinding("SH600030",UUID.randomUUID().toString()),new com.aistock.common.marketlifecycle.MarketUseRecords.EvidenceBinding("SH600276",UUID.randomUUID().toString())),null);try(var scope=com.aistock.prediction.marketuse.MarketUseContext.open(new com.aistock.prediction.marketuse.MarketUseClient.Request(execution,"1",UUID.randomUUID().toString(),"COMPARISON",selected),new com.aistock.prediction.marketuse.MarketUseClient.Receipt(bundle,"ACTIVE",List.of(UUID.randomUUID().toString(),UUID.randomUUID().toString())))){var c=new HttpComparisonMarketClient("http://127.0.0.1:"+server.getAddress().getPort(),"fixture",new ObjectMapper());assertEquals(70000,c.evidence(UUID.randomUUID()).path("padding").asText().length());}finally{server.stop(0);}}
 @Test void rejectsOversizeRedirectAndMissingToken()throws Exception{for(int code:new int[]{200,302,503}){var server=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);server.createContext("/",e->{var bytes="x".repeat(524289).getBytes();e.sendResponseHeaders(code,bytes.length);try{e.getResponseBody().write(bytes);}catch(Exception ignored){}e.close();});server.start();try{var c=new HttpComparisonMarketClient("http://127.0.0.1:"+server.getAddress().getPort(),"fixture",new ObjectMapper());assertThrows(RuntimeException.class,()->c.evidence(UUID.randomUUID()));}finally{server.stop(0);}}assertThrows(RuntimeException.class,()->new HttpComparisonMarketClient("http://127.0.0.1:1","",new ObjectMapper()).evidence(UUID.randomUUID()));}
 @Test void boundsSlowBodyAndRejectsTruncatedResponse()throws Exception{for(boolean slow:new boolean[]{true,false}){var server=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);server.createContext("/",e->{e.sendResponseHeaders(200,100);try{e.getResponseBody().write("{\"code\":\"OK\",".getBytes());e.getResponseBody().flush();if(slow)Thread.sleep(1800);}catch(Exception ignored){}finally{e.close();}});server.start();try{var transport=new BoundedComparisonHttp("fixture",new ObjectMapper());long start=System.nanoTime();assertThrows(RuntimeException.class,()->transport.call("http://127.0.0.1:"+server.getAddress().getPort(),"/",null,1));assertTrue(java.util.concurrent.TimeUnit.NANOSECONDS.toMillis(System.nanoTime()-start)<1700);}finally{server.stop(0);}}}
}
